// Serialized per-file mutex queue di level modul agar penulisan/patching paralel antar sub-agen Z21 tidak pernah saling menimpa
const __workspaceFileLocks = new Map();
function withWorkspaceFileLock(fullPath, fn) {
  const lockKey = process.platform === 'win32' ? String(fullPath || '').toLowerCase() : String(fullPath || '');
  const prev = __workspaceFileLocks.get(lockKey) || Promise.resolve();
  const run = prev.catch(() => {}).then(fn);
  const tail = run.finally(() => {
    if (__workspaceFileLocks.get(lockKey) === tail) {
      __workspaceFileLocks.delete(lockKey);
    }
  });
  __workspaceFileLocks.set(lockKey, tail);
  return run;
}

// =========================================================================
// CLOUDFLARE TUNNEL REMOTE ACCESS (WAN Mobile-to-Desktop) STATE & ENGINE
// =========================================================================
function isPidAlive(pid) {
  if (!pid) return false;
  try {
    process.kill(pid, 0);
    return true;
  } catch (_) {
    return false;
  }
}

const TUNNEL_STATE_FILE = path.join(__dirname, 'data', 'tunnel-state.json');
const SYSTEM_BOOT_TIME = Math.round(Date.now() / 1000 - os.uptime());
let persistedTunnel = null;
try {
  if (fs.existsSync(TUNNEL_STATE_FILE)) {
    persistedTunnel = JSON.parse(fs.readFileSync(TUNNEL_STATE_FILE, 'utf8'));
  }
} catch (_) {}

function extractLatestTunnelUrlFromLog() {
  const logPaths = [
    path.join(__dirname, 'data', 'cloudflared-service.log'),
    path.join(__dirname, 'data', 'cloudflared.log')
  ];
  for (const lp of logPaths) {
    try {
      if (fs.existsSync(lp)) {
        const content = fs.readFileSync(lp, 'utf8');
        const matches = content.match(/https:\/\/[a-zA-Z0-9-]+\.trycloudflare\.com/g);
        if (matches && matches.length > 0) {
          return matches[matches.length - 1].trim();
        }
      }
    } catch (_) {}
  }
  return null;
}

function isTunnelZombieDead() {
  const logPaths = [
    path.join(__dirname, 'data', 'cloudflared-service.log'),
    path.join(__dirname, 'data', 'cloudflared.log')
  ];
  for (const lp of logPaths) {
    try {
      if (fs.existsSync(lp)) {
        const content = fs.readFileSync(lp, 'utf8');
        const tail = content.slice(-4000);
        if (tail.includes('Unauthorized: Tunnel not found') || tail.includes('Register tunnel error')) {
          return true;
        }
      }
    } catch (_) {}
  }
  return false;
}

let cloudflareTunnelProcess = null;
let cloudflareTunnelPid = null;

function findRunningCloudflaredPid() {
  if (cloudflareTunnelProcess && cloudflareTunnelProcess.pid && isPidAlive(cloudflareTunnelProcess.pid)) {
    return cloudflareTunnelProcess.pid;
  }
  if (cloudflareTunnelPid && isPidAlive(cloudflareTunnelPid)) {
    return cloudflareTunnelPid;
  }
  if (persistedTunnel && persistedTunnel.pid && isPidAlive(persistedTunnel.pid)) {
    return persistedTunnel.pid;
  }
  if (process.platform === 'win32') {
    try {
      const out = execSync('tasklist /FI "IMAGENAME eq cloudflared.exe" /FO CSV /NH', { encoding: 'utf8', timeout: 3000 });
      const match = out.match(/"cloudflared\.exe","(\d+)"/i);
      if (match && match[1]) {
        const foundPid = parseInt(match[1], 10);
        if (isPidAlive(foundPid)) return foundPid;
      }
    } catch (_) {}
  }
  return null;
}

cloudflareTunnelPid = findRunningCloudflaredPid();
let cloudflareTunnelUrl = extractLatestTunnelUrlFromLog() || (persistedTunnel && persistedTunnel.url) || '';
let cloudflareTunnelActive = Boolean(cloudflareTunnelPid && cloudflareTunnelUrl);
let cloudflareTunnelError = '';
// Persistent PIN: Keep identical PIN across server restarts for this laptop uptime
let cloudflareTunnelPin = (persistedTunnel && persistedTunnel.pin)
  ? String(persistedTunnel.pin).trim()
  : generateSixDigitPin();
let cloudflareTunnelStartedAt = (persistedTunnel && persistedTunnel.startedAt) || null;
let isTunnelIntentionallyStopped = false;
let globalAutoEnterEnabled = false;

function savePersistedTunnelState() {
  try {
    const dir = path.join(__dirname, 'data');
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
    const payload = {
      url: cloudflareTunnelUrl,
      pin: cloudflareTunnelPin,
      pid: cloudflareTunnelPid,
      startedAt: cloudflareTunnelStartedAt,
      bootTime: SYSTEM_BOOT_TIME,
      autoEnter: globalAutoEnterEnabled,
      updatedAt: new Date().toISOString()
    };
    fs.writeFileSync(TUNNEL_STATE_FILE, JSON.stringify(payload, null, 2));
    persistedTunnel = payload;
  } catch (_) {}
  scheduleEdgeTunnelSync(cloudflareTunnelUrl);
}

// ===== AUTO-SYNC URL TUNNEL KE EDGE (Cloudflare Pages z21.zozdocs.com) =====
// Quick tunnel trycloudflare mendapat URL BARU setiap kali cloudflared di-restart,
// sedangkan _worker.js & app.js (yang dilayani Cloudflare Pages) meng-hardcode URL tunnel.
// Tanpa sinkronisasi, seluruh request dari z21.zozdocs.com menembak tunnel mati → "Failed to fetch".
// Fungsi ini menulis ulang konstanta URL tunnel lalu commit + push (memicu redeploy Pages).
// Nonaktifkan dengan env ZOZ_AUTO_TUNNEL_SYNC=0.
const EDGE_TUNNEL_SYNC_TARGETS = [
  { file: '_worker.js', patterns: [/(TUNNEL_GATEWAY_URL\s*=\s*(?:String\(\(env\s*&&\s*env\.TUNNEL_GATEWAY_URL\)\s*\|\|\s*)?')https:\/\/[a-z0-9-]+\.trycloudflare\.com(')/] },
  { file: 'app.js', patterns: [/(const ACTIVE_CLOUDFLARE_TUNNEL = ')https:\/\/[a-z0-9-]+\.trycloudflare\.com(')/, /(activeTunnelUrl: ')https:\/\/[a-z0-9-]+\.trycloudflare\.com(')/] },
  { file: path.join('public', 'app.js'), patterns: [/(const ACTIVE_CLOUDFLARE_TUNNEL = ')https:\/\/[a-z0-9-]+\.trycloudflare\.com(')/, /(activeTunnelUrl: ')https:\/\/[a-z0-9-]+\.trycloudflare\.com(')/] }
];
let edgeTunnelSyncTimer = null;
let edgeTunnelSyncInFlight = false;
let edgeTunnelLastSyncedUrl = '';

function scheduleEdgeTunnelSync(url) {
  if (process.env.ZOZ_AUTO_TUNNEL_SYNC === '0' || process.env.VERCEL || process.env.AWS_LAMBDA_FUNCTION_NAME) return;
  if (!url || !/^https:\/\/[a-z0-9-]+\.trycloudflare\.com$/i.test(url) || url === edgeTunnelLastSyncedUrl) return;
  if (edgeTunnelSyncTimer) clearTimeout(edgeTunnelSyncTimer);
  // Debounce: beri waktu tunnel benar-benar stabil sebelum men-deploy
  edgeTunnelSyncTimer = setTimeout(() => { edgeTunnelSyncTimer = null; syncTunnelUrlToEdge(url); }, 8000);
}

function runGit(args) {
  return new Promise((resolve) => {
    execFile('git', args, { cwd: __dirname, windowsHide: true, timeout: 60000 }, (err, stdout, stderr) => {
      resolve({ ok: !err, stdout: String(stdout || ''), stderr: String(stderr || (err && err.message) || '') });
    });
  });
}

async function syncTunnelUrlToEdge(url) {
  if (edgeTunnelSyncInFlight) { scheduleEdgeTunnelSync(url); return; }
  edgeTunnelSyncInFlight = true;
  try {
    const changedFiles = [];
    for (const target of EDGE_TUNNEL_SYNC_TARGETS) {
      const abs = path.join(__dirname, target.file);
      if (!fs.existsSync(abs)) continue;
      const original = fs.readFileSync(abs, 'utf8');
      let updated = original;
      for (const re of target.patterns) updated = updated.replace(re, `$1${url}$2`);
      if (updated !== original) {
        fs.writeFileSync(abs, updated, 'utf8');
        changedFiles.push(target.file.split(path.sep).join('/'));
      }
    }
    if (changedFiles.length === 0) {
      if (fs.existsSync(path.join(__dirname, '.git'))) {
        // Jika berkas sudah tertulis namun push sebelumnya sempat gagal, coba dorong ulang ke origin
        const retryPush = await runGit(['push', 'origin', 'HEAD']);
        if (retryPush.ok) {
          edgeTunnelLastSyncedUrl = url;
        }
      } else {
        edgeTunnelLastSyncedUrl = url;
      }
      return;
    }

    // Bump cache-buster pada index.html agar browser seluler pengguna otomatis flush cache & baca tunnel baru
    const newEdgeVer = 'v' + new Date().toISOString().slice(0, 10).replace(/-/g, '') + '_t' + Date.now().toString(36);
    for (const idxFile of ['index.html', path.join('public', 'index.html')]) {
      const absIdx = path.join(__dirname, idxFile);
      if (fs.existsSync(absIdx)) {
        let idxContent = fs.readFileSync(absIdx, 'utf8');
        idxContent = idxContent.replace(/(var currentVer = ')[^']+(')/, `$1${newEdgeVer}$2`)
                               .replace(/(window\.__ZOZ_VERSION__ = ')[^']+(')/, `$1${newEdgeVer}$2`)
                               .replace(/(<link [^>]*href="style\.css\?v=)[^"]+(")/g, `$1${newEdgeVer}$2`)
                               .replace(/(<script src="text-safety\.js\?v=)[^"]+(")/, `$1${newEdgeVer}$2`)
                               .replace(/(<script src="app\.js\?v=)[^"]+(")/, `$1${newEdgeVer}$2`);
        fs.writeFileSync(absIdx, idxContent, 'utf8');
        changedFiles.push(idxFile.split(path.sep).join('/'));
      }
    }

    console.log(`[Edge Tunnel Sync] URL tunnel baru ditulis ke: ${changedFiles.join(', ')}`);
    if (!fs.existsSync(path.join(__dirname, '.git'))) {
      edgeTunnelLastSyncedUrl = url;
      return;
    }
    const add = await runGit(['add', '--', ...changedFiles]);
    if (!add.ok) return console.warn('[Edge Tunnel Sync] git add gagal:', add.stderr.trim());
    const commit = await runGit(['commit', '-m', `chore(tunnel): auto-sync active tunnel ${url}`, '--', ...changedFiles]);
    if (!commit.ok) return console.warn('[Edge Tunnel Sync] git commit gagal:', commit.stderr.trim());
    const push = await runGit(['push', 'origin', 'HEAD']);
    if (!push.ok) return console.warn('[Edge Tunnel Sync] git push gagal:', push.stderr.trim());
    edgeTunnelLastSyncedUrl = url;
    console.log('[Edge Tunnel Sync] Terdorong ke origin — Cloudflare Pages akan redeploy otomatis.');
  } catch (err) {
    console.warn('[Edge Tunnel Sync] Gagal:', err && err.message);
  } finally {
    edgeTunnelSyncInFlight = false;
  }
}

// Initial state persistence ensuring PIN is locked to disk
savePersistedTunnelState();

function generateSixDigitPin() {
  return String(crypto.randomInt(100000, 1000000));
}

function getCloudflaredBinaryPath() {
  const localBin = path.join(__dirname, 'bin', 'cloudflared.exe');
  if (fs.existsSync(localBin)) return localBin;
  const localBinNoExt = path.join(__dirname, 'bin', 'cloudflared');
  if (fs.existsSync(localBinNoExt)) return localBinNoExt;
  return 'cloudflared';
}

function startCloudflareTunnel(customPort, forceRestart = false) {
  isTunnelIntentionallyStopped = false;
  return new Promise((resolve) => {
    // 1. Re-check running cloudflared process on Windows host
    const runningPid = findRunningCloudflaredPid();
    const latestUrlInLog = extractLatestTunnelUrlFromLog();
    const isZombie = isTunnelZombieDead();

    if (!forceRestart && !isZombie && runningPid && latestUrlInLog) {
      cloudflareTunnelPid = runningPid;
      cloudflareTunnelUrl = latestUrlInLog;
      cloudflareTunnelActive = true;
      cloudflareTunnelStartedAt = (persistedTunnel && persistedTunnel.startedAt) || new Date().toISOString();
      savePersistedTunnelState();
      console.log(`[Cloudflare] Detached Tunnel Reused (PID ${cloudflareTunnelPid}): ${cloudflareTunnelUrl} (PIN: ${cloudflareTunnelPin})`);
      return resolve({
        active: true,
        tunnelUrl: cloudflareTunnelUrl,
        wssUrl: cloudflareTunnelUrl.replace(/^http/i, 'ws'),
        pin: cloudflareTunnelPin,
        startedAt: cloudflareTunnelStartedAt
      });
    }

    if (cloudflareTunnelProcess) {
      try { cloudflareTunnelProcess.kill(); } catch (_) {}
      cloudflareTunnelProcess = null;
    }
    if (process.platform === 'win32') {
      try {
        execSync('taskkill /F /IM cloudflared.exe /T', { stdio: 'ignore' });
      } catch (_) {}
    }

    cloudflareTunnelActive = false;
    cloudflareTunnelError = '';
    cloudflareTunnelUrl = '';

    const binPath = getCloudflaredBinaryPath();
    const targetPort = customPort || process.env.PORT || 4040;
    const logFilePath = path.join(__dirname, 'data', 'cloudflared-service.log');

    try {
      const dataDir = path.join(__dirname, 'data');
      if (!fs.existsSync(dataDir)) fs.mkdirSync(dataDir, { recursive: true });
      // Bersihkan berkas log sebelum menjalankan cloudflared baru agar tidak membaca URL lama yang kedaluwarsa
      fs.writeFileSync(logFilePath, '');
    } catch (_) {}

    const args = ['tunnel', '--url', `http://localhost:${targetPort}`, '--no-autoupdate', '--logfile', logFilePath];

    try {
      cloudflareTunnelProcess = spawn(binPath, args, {
        windowsHide: true,
        detached: true,
        stdio: 'ignore'
      });
      cloudflareTunnelPid = cloudflareTunnelProcess.pid;
      cloudflareTunnelProcess.unref();
    } catch (err) {
      cloudflareTunnelError = `Gagal menjalankan cloudflared: ${err.message}.`;
      return resolve({
        active: false,
        tunnelUrl: '',
        wssUrl: '',
        pin: cloudflareTunnelPin,
        error: cloudflareTunnelError
      });
    }

    let resolved = false;
    let pollCount = 0;
    const pollInterval = setInterval(() => {
      pollCount++;
      const detected = extractLatestTunnelUrlFromLog();
      if (detected) {
        clearInterval(pollInterval);
        clearTimeout(timeoutTimer);
        cloudflareTunnelUrl = detected;
        cloudflareTunnelActive = true;
        cloudflareTunnelStartedAt = new Date().toISOString();
        savePersistedTunnelState();
        console.log(`[Cloudflare] Tunnel Host Persistent: ${cloudflareTunnelUrl} (PIN: ${cloudflareTunnelPin})`);
        if (!resolved) {
          resolved = true;
          resolve({
            active: true,
            tunnelUrl: cloudflareTunnelUrl,
            wssUrl: cloudflareTunnelUrl.replace(/^http/i, 'ws'),
            pin: cloudflareTunnelPin,
            startedAt: cloudflareTunnelStartedAt
          });
        }
      } else if (pollCount > 60) {
        clearInterval(pollInterval);
      }
    }, 500);

    const timeoutTimer = setTimeout(() => {
      clearInterval(pollInterval);
      if (!resolved) {
        resolved = true;
        const fallbackUrl = extractLatestTunnelUrlFromLog();
        if (fallbackUrl) {
          cloudflareTunnelUrl = fallbackUrl;
          cloudflareTunnelActive = true;
          savePersistedTunnelState();
          resolve({
            active: true,
            tunnelUrl: cloudflareTunnelUrl,
            wssUrl: cloudflareTunnelUrl.replace(/^http/i, 'ws'),
            pin: cloudflareTunnelPin,
            startedAt: cloudflareTunnelStartedAt
          });
        } else {
          resolve({
            active: false,
            tunnelUrl: '',
            wssUrl: '',
            pin: cloudflareTunnelPin,
            error: cloudflareTunnelError || 'Waktu tunggu pembuatan tunnel Cloudflare habis. Periksa koneksi internet.'
          });
        }
      }
    }, 30000);
  });
}

function stopCloudflareTunnel() {
  isTunnelIntentionallyStopped = true;
  if (cloudflareTunnelProcess) {
    try { cloudflareTunnelProcess.kill(); } catch (_) {}
    cloudflareTunnelProcess = null;
  }
  if (cloudflareTunnelPid && isPidAlive(cloudflareTunnelPid)) {
    try {
      if (process.platform === 'win32') {
        execSync(`taskkill /F /PID ${cloudflareTunnelPid} /T`, { stdio: 'ignore' });
      } else {
        process.kill(cloudflareTunnelPid);
      }
    } catch (_) {}
  }
  if (process.platform === 'win32') {
    try {
      execSync('taskkill /F /IM cloudflared.exe /T', { stdio: 'ignore' });
    } catch (_) {}
  }
  cloudflareTunnelActive = false;
  cloudflareTunnelPid = null;
  cloudflareTunnelUrl = '';
  savePersistedTunnelState();
  return { active: false, message: 'Cloudflare Tunnel dimatikan.' };
}

const STRICT_LOCAL_HOST_RE = /^(?:localhost|127\.0\.0\.1|\[::1\])(?::\d{1,5})?$/i;

function isRemoteTunnelRequest(req) {
  if (!req || !req.headers) return false;
  const host = String(req.headers.host || '').trim().toLowerCase();
  const proxyOrTunnelHeader = Boolean(
    req.headers['cf-connecting-ip'] ||
    req.headers['cf-ray'] ||
    req.headers['cf-visitor'] ||
    req.headers['x-forwarded-host'] ||
    req.headers['x-forwarded-for'] ||
    req.headers['x-forwarded-proto'] ||
    req.headers['forwarded'] ||
    req.headers['x-real-ip'] ||
    req.headers['true-client-ip'] ||
    req.headers['x-vercel-id']
  );
  if (proxyOrTunnelHeader || host.includes('trycloudflare.com')) {
    return true;
  }
  const remoteIp = req.socket?.remoteAddress || req.connection?.remoteAddress || '';
  if (remoteIp && remoteIp !== '127.0.0.1' && remoteIp !== '::1' && remoteIp !== '::ffff:127.0.0.1') {
    return true;
  }
  if (host && !STRICT_LOCAL_HOST_RE.test(host)) {
    return true;
  }
  return false;
}

function extractCookiePin(req) {
  const cookieHeader = req && req.headers && req.headers.cookie;
  if (!cookieHeader) return null;
  const match = cookieHeader.match(/(?:^|;\s*)zoz_remote_pin=([0-9a-zA-Z_-]+)/);
  return match ? decodeURIComponent(match[1]).trim() : null;
}

function constantTimePinEqual(a, b) {
  if (!a || !b || typeof a !== 'string' || typeof b !== 'string') return false;
  const bufA = Buffer.from(a, 'utf8');
  const bufB = Buffer.from(b, 'utf8');
  if (bufA.length !== bufB.length) return false;
  try {
    return crypto.timingSafeEqual(bufA, bufB);
  } catch (_) {
    return false;
  }
}

const remotePinFailTracker = new Map(); // ip -> { count, resetAt }

function getRemoteClientIp(req) {
  const cfIp = req && req.headers && (req.headers['cf-connecting-ip'] || req.headers['x-forwarded-for']);
  if (cfIp) return String(cfIp).split(',')[0].trim();
  return String((req && req.socket && req.socket.remoteAddress) || 'unknown');
}

function buildRemotePinCookie(req, pinValue) {
  const proto = String((req && req.headers && req.headers['x-forwarded-proto']) || '').toLowerCase();
  const isHttps = proto === 'https' || Boolean(req && req.socket && req.socket.encrypted) || isRemoteTunnelRequest(req);
  const secureFlag = isHttps ? '; Secure' : '';
  return `zoz_remote_pin=${encodeURIComponent(pinValue)}; Path=/; Max-Age=2592000; SameSite=Lax${secureFlag}`;
}

function validateRemoteTerminalPin(req, reqUrl, body) {
  if (!isRemoteTunnelRequest(req)) {
    return { valid: true };
  }
  const clientIp = getRemoteClientIp(req);
  const now = Date.now();
  const tracker = remotePinFailTracker.get(clientIp);
  if (tracker && tracker.resetAt > now && tracker.count >= 25) {
    return {
      valid: false,
      status: 429,
      error: 'Terlalu banyak percobaan PIN salah. Tunggu beberapa menit sebelum mencoba lagi.'
    };
  }
  if (tracker && tracker.resetAt <= now) {
    remotePinFailTracker.delete(clientIp);
  }

  const clientPin = (reqUrl && reqUrl.searchParams && reqUrl.searchParams.get('pin')) ||
                    (req && req.headers && req.headers['x-terminal-pin']) ||
                    (body && body.pin) ||
                    extractCookiePin(req);
  const cleanPin = clientPin ? String(clientPin).trim() : '';
  const tunnelPin = cloudflareTunnelPin ? String(cloudflareTunnelPin).trim() : '';
  const matchedTunnelPin = constantTimePinEqual(cleanPin, tunnelPin);
  const isMasterPinValid = Boolean(
    cleanPin &&
    waGatewayManager &&
    waGatewayManager.masterGateway &&
    (waGatewayManager.masterGateway.hasConfiguredPin?.() || Boolean(process.env.ZOZ_MASTER_PIN)) &&
    typeof waGatewayManager.masterGateway.verifyPin === 'function' &&
    waGatewayManager.masterGateway.verifyPin(cleanPin)
  );
  if (!cleanPin || (!matchedTunnelPin && !isMasterPinValid)) {
    if (cleanPin) {
      const cur = remotePinFailTracker.get(clientIp);
      if (!cur || cur.resetAt <= now) {
        if (remotePinFailTracker.size > 500) remotePinFailTracker.clear();
        remotePinFailTracker.set(clientIp, { count: 1, resetAt: now + 5 * 60 * 1000 });
      } else {
        cur.count += 1;
      }
    }
    return {
      valid: false,
      status: 401,
      error: 'PIN autentikasi remote tidak valid. Masukkan PIN 6-digit dari laptop host.'
    };
  }
  remotePinFailTracker.delete(clientIp);
  return { valid: true, matchedTunnelPin };
}

function requireRemoteHostPin(req, res, reqUrl, body = null) {
  const pinCheck = validateRemoteTerminalPin(req, reqUrl, body);
  if (!pinCheck.valid) {
    sendJSON(res, pinCheck.status || 401, { success: false, error: pinCheck.error });
    return false;
  }
  return true;
}

function resolveHostShell(shellType) {
  const isWin = process.platform === 'win32';
  const type = (shellType || 'powershell').toLowerCase();
  if (type === 'cmd' || type === 'cmd.exe') {
    return { exe: isWin ? 'cmd.exe' : 'sh', args: [] };
  }
  if (type === 'wsl' || type === 'bash' || type === 'ubuntu-wsl') {
    return { exe: isWin ? 'wsl.exe' : 'bash', args: isWin ? ['-e', 'bash'] : [] };
  }
  if (type === 'node') {
    return { exe: process.execPath, args: [] };
  }
  if (type === 'python') {
    return { exe: isWin ? 'python.exe' : 'python3', args: ['-i'] };
  }
  // Default: PowerShell dengan $PROFILE termuat utuh (tanpa -NoProfile)
  // Nonaktifkan PSReadLine Inline/History Prediction agar tidak membungkus (wrap) teks prediksi
  // abu-abu panjang yang mengacaukan koordinat baris/kolom pada layar sempit ponsel.
  return {
    exe: isWin ? 'powershell.exe' : 'pwsh',
    args: isWin
      ? ['-NoLogo', '-ExecutionPolicy', 'Bypass', '-NoExit', '-Command', 'try { Import-Module PSReadLine -ErrorAction SilentlyContinue; Set-PSReadLineOption -PredictionSource None -ErrorAction SilentlyContinue } catch {}']
      : ['-NoLogo', '-ExecutionPolicy', 'Bypass']
  };
}

/**
 * Helper deteksi ada atau tidaknya teks prompt terminal yang tampak (visible prompt).
 * Memeriksa apakah buffer berisi teks alfanumerik nyata setelah membersihkan seluruh kode ANSI CSI, OSC, dan control sequences.
 */
function hasVisibleTerminalPrompt(bufferStr) {
  if (!bufferStr) return false;
  const stripped = bufferStr
    .replace(/\x1b\][^\x07\x1b]*(\x07|\x1b\\)/g, '')
    .replace(/\x1b\[[0-9;? -/]*[@-~]/g, '')
    .replace(/\x1b[()][A-Za-z0-9]/g, '')
    .replace(/[\x00-\x1f\x7f]/g, ' ')
    .trim();
  return stripped.length >= 2;
}

/**
 * Normalisasi input PTY berbasis jenis shell target:
 * - UNIX / WSL / Node / Python / non-Windows: pertahankan Alt+Backspace (\x1b\x7f, \x1b\x08) seutuhnya.
 * - PowerShell Windows ConPTY: petakan Alt+Backspace (\x1b\x7f, \x1b\x08) ke \x17 (Ctrl+W BackwardKillWord)
 *   agar menghapus satu kata utuh tanpa memicu echo ^H / ^¿ dari ConPTY.
 * - CMD Windows ConPTY: petakan ke \x08 (Backspace standar cmd.exe).
 */
function sanitizePtyInputForShell(sessionOrShell, rawData) {
  if (typeof rawData !== 'string' || !rawData) return rawData || '';
  if (process.platform !== 'win32') return rawData;
  const shell = (typeof sessionOrShell === 'string' ? sessionOrShell : sessionOrShell?.shell || 'powershell').toLowerCase();
  if (shell === 'wsl' || shell === 'bash' || shell === 'ubuntu-wsl' || shell === 'node' || shell === 'python') {
    return rawData;
  }
  if (shell === 'cmd' || shell === 'cmd.exe') {
    return rawData.replace(/\x1b\x7f/g, '\x08').replace(/\x1b\x08/g, '\x08');
  }
  return rawData.replace(/\x1b\x7f/g, '\x17').replace(/\x1b\x08/g, '\x17');
}

/**
 * Pemotongan buffer replay terminal (maks maxChars) secara aman pada batas chunk
 * atau melangkahi fragmen sekuens ANSI incomplete agar output reconnect tidak terpotong di tengah kode escape.
 */
function sliceReplayBufferSafely(chunks, maxChars = 65536) {
  if (!Array.isArray(chunks) || chunks.length === 0) return '';
  const selected = [];
  let total = 0;
  for (let i = chunks.length - 1; i >= 0; i--) {
    const ch = chunks[i];
    if (!ch) continue;
    if (total + ch.length <= maxChars) {
      selected.push(ch);
      total += ch.length;
    } else {
      if (selected.length === 0) {
        let tail = ch.slice(-maxChars);
        const firstEsc = tail.indexOf('\x1b');
        const firstNl = tail.indexOf('\n');
        if (firstEsc > 0 && firstNl !== -1 && firstNl < firstEsc) {
          tail = tail.slice(firstNl + 1);
        } else if (tail.startsWith('[') || tail.startsWith(']')) {
          if (firstNl !== -1 && firstNl < 256) tail = tail.slice(firstNl + 1);
          else if (firstEsc > 0) tail = tail.slice(firstEsc);
        }
        selected.push(tail);
      }
      break;
    }
  }
  return selected.reverse().join('');
}

/**
 * Membersihkan seluruh timer, PTY, socket WebSocket, dan SSE client dari satu sesi terminal secara atomik.
 */
function destroyTerminalSession(sessionId, session) {
  if (session) {
    if (session._autoEnterRetryTimer) {
      clearTimeout(session._autoEnterRetryTimer);
      session._autoEnterRetryTimer = null;
    }
    if (session._autoEnterActionTimer) {
      clearTimeout(session._autoEnterActionTimer);
      session._autoEnterActionTimer = null;
    }
    if (session._resizeTimer) {
      clearTimeout(session._resizeTimer);
      session._resizeTimer = null;
    }
    if (session._disconnectTimer) {
      clearTimeout(session._disconnectTimer);
      session._disconnectTimer = null;
    }
    if (session._wsFlushTimer) {
      clearTimeout(session._wsFlushTimer);
      session._wsFlushTimer = null;
    }
    const ptyProc = session.pty;
    session.pty = null;
    try {
      if (ptyProc && typeof ptyProc.kill === 'function') ptyProc.kill();
    } catch (_) {}
    if (session.clients) {
      for (const client of session.clients) {
        try { if (!client.writableEnded) client.end(); } catch (_) {}
      }
      session.clients.clear();
    }
    if (session.wsClients) {
      for (const ws of session.wsClients) {
        try {
          if (ws.writable) {
            ws.write(encodeWsFrame(JSON.stringify({ type: 'exit', exitCode: 0, signal: 'SIGTERM' })));
            ws.end();
          } else {
            ws.destroy();
          }
        } catch (_) {
          try { ws.destroy(); } catch (__) {}
        }
      }
      session.wsClients.clear();
    }
  }
  if (sessionId) {
    activeTerminalSessions.delete(sessionId);
    if (typeof sessionAutoEnterState !== 'undefined' && sessionAutoEnterState) {
      sessionAutoEnterState.delete(sessionId);
    }
  }
}

/**
 * Helper normalisasi stream ConPTY Windows di level global (Linear-Time O(N) Zero-Backtracking)
 * untuk memurnikan sekuens hapus layar (cls / Clear-Host) tanpa risiko ReDoS pada TUI besar (codex/agy).
 * Diakses oleh jalur SSE (/api/terminal/stream) maupun jalur WebSocket (handleTerminalWebSocketUpgrade).
 */
function cleanConptyData(str, sessionOrPane) {
  if (typeof str !== 'string' || !str) return str;

  const hasScreenClearOrErase = str.includes('\x1b[2J') || str.includes('\x1b[3J') || str.includes('\x1b[H') || str.includes('\x1b[1;') || str.includes('\x1b[J') || str.includes('\x1bc');

  // Cross-chunk horizontal duplicate prompt elimination:
  if (sessionOrPane && sessionOrPane._lastHorizontalPrompt) {
    const lastPrompt = sessionOrPane._lastHorizontalPrompt;
    if (str.indexOf('\x1b') === -1) {
      if (str.startsWith(lastPrompt)) {
        str = str.slice(lastPrompt.length).replace(/^[ \t]+/, '');
        if (!str) return '';
      }
    } else if (!hasScreenClearOrErase) {
      const escaped = lastPrompt.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      const leadRe = new RegExp('^(?:\\x1b\\[[0-9;?]*[a-zA-Z])*' + escaped + '[ \\t]*');
      if (leadRe.test(str)) {
        str = str.replace(leadRe, '');
        if (!str) return '';
      }
    }
  }

  if (str.indexOf('\x1b') === -1) {
    if (sessionOrPane) {
      const pEnd = str.match(/PS [A-Za-z]:\\[^\r\n>]*>[ \t]*$/);
      if (pEnd) {
        sessionOrPane._lastHorizontalPrompt = pEnd[0].trim();
      } else if (str.includes('\n') || str.includes('\r')) {
        sessionOrPane._lastHorizontalPrompt = '';
      }
    }
    return str;
  }

  // 1. Deteksi ConPTY screen wipe: loop pembersihan baris (\x1b[K\r\n) yang diakhiri cursor home (\x1b[H / \x1b[1;1H / \x1b[1;colH)
  const homePositions = [];
  let pos = -1;
  while ((pos = str.indexOf('\x1b[H', pos + 1)) !== -1) homePositions.push({ idx: pos, len: 3, col: 1 });
  pos = -1;
  while ((pos = str.indexOf('\x1b[1;', pos + 1)) !== -1) {
    const endH = str.indexOf('H', pos);
    if (endH !== -1 && endH <= pos + 8) {
      const colStr = str.slice(pos + 4, endH);
      if (/^\d+$/.test(colStr)) {
        homePositions.push({ idx: pos, len: endH - pos + 1, col: parseInt(colStr, 10) });
      }
    }
  }

  // Urutkan dari indeks terbesar ke terkecil agar pemotongan string tidak merusak offset
  homePositions.sort((a, b) => b.idx - a.idx);

  for (const { idx: targetIdx, len: seqLen, col } of homePositions) {
    let startIdx = targetIdx;
    let kCount = 0;
    while (startIdx > 0) {
      const prevChar = str[startIdx - 1];
      if (prevChar === '\n' || prevChar === '\r') {
        startIdx--;
        continue;
      }
      if (startIdx >= 3 && str.slice(startIdx - 3, startIdx) === '\x1b[K') {
        kCount++;
        startIdx -= 3;
        continue;
      }
      if (startIdx >= 4 && str.slice(startIdx - 4, startIdx) === '\x1b[2K') {
        kCount++;
        startIdx -= 4;
        continue;
      }
      if (prevChar === 'm' || prevChar === 'l' || prevChar === 'h') {
        const escPos = str.lastIndexOf('\x1b[', startIdx - 1);
        if (escPos !== -1 && escPos >= startIdx - 30 && /^\x1b\[[0-9;?]*[mlh]$/.test(str.slice(escPos, startIdx))) {
          startIdx = escPos;
          continue;
        }
      }
      break;
    }

    if (kCount >= 3) {
      const afterTarget = targetIdx + seqLen;
      const seqStr = str.slice(targetIdx, afterTarget);
      if (col > 1) {
        // ConPTY top-down prompt redraw (\x1b[?25lPS C:\...>\x1b[K\r\n...\x1b[1;19H\x1b[?25h):
        // Pertahankan prompt baris-1 & kursor, ganti hanya wipe loop dengan erase-to-end-of-screen (\x1b[K\x1b[J).
        str = str.slice(0, startIdx) + '\x1b[K\x1b[J' + seqStr + str.slice(afterTarget);
      } else {
        // Full-screen wipe sebelum redraw (\x1b[K\r\n...\x1b[H):
        // Ganti loop destruktif dengan clear screen ANSI murni tanpa menelan \x1b[?25h (visibilitas kursor).
        str = str.slice(0, startIdx) + '\x1b[2J\x1b[3J\x1b[H' + str.slice(afterTarget);
      }
    }
  }

  // 2. Dedup prompt kembar horizontal di baris yang sama (mis. "PS C:\...> PS C:\...>") secara linear O(N)
  const dIdx = str.indexOf('PS ');
  if (dIdx !== -1) {
    str = str.replace(/(PS [A-Za-z]:\\[^\r\n>]*>)[ \t]*(?:\x1b\[[0-9;?]*[a-zA-Z])*[ \t]*\1[ \t]*/g, '$1 ');
  }

  // Update status prompt horizontal terakhir
  if (sessionOrPane) {
    const pEnd = str.match(/PS [A-Za-z]:\\[^\r\n>]*>[ \t]*$/);
    if (pEnd) {
      sessionOrPane._lastHorizontalPrompt = pEnd[0].trim();
    } else if (
      str.includes('\n') ||
      str.includes('\r') ||
      str.includes('\x1b[2J') ||
      str.includes('\x1b[3J') ||
      str.includes('\x1b[H') ||
      str.includes('\x1b[J') ||
      str.includes('\x1bc')
    ) {
      sessionOrPane._lastHorizontalPrompt = '';
    }
  }

  return str;
}

/**
 * Normalisasi deterministik chunk output terminal (ANSI/ConPTY) untuk pendeteksi prompt Auto Enter.
 * Mempartisi sekuens escape secara matematis:
 * - OSC & SGR styling/mode (m/h/l/K/...) -> '' (menjaga token terpecah antar chunk seperti '[y' + '/N]' tetap utuh)
 * - Pergerakan kursor & pembersihan layar (H/f/C/G/J/...) & CR/LF -> ' ' (menjaga batas kata TUI)
 */
function stripTerminalAnsiForMatcher(rawData) {
  if (!rawData || typeof rawData !== 'string') return '';
  return rawData
    .replace(/\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)/g, '')
    .replace(/\x1b\[[0-9;?]*[mhlrsuK]/g, '')
    .replace(/\x1b\[[0-9;?]*[@-~]/g, ' ')
    .replace(/\x1b[@-Z\\-_]/g, '')
    .replace(/\r\n?/g, '\n')
    .replace(/[\x00-\x08\x0B-\x1F\x7F]/g, '');
}

/**
 * Selalu rekam jendela geser output PTY (3000 char) terlepas dari status autoEnter OFF/ON.
 * Invarian: Jika prompt muncul saat Auto Enter OFF lalu pengguna menyalakannya kembali (0 -> 1),
 * tail prompt masih tersimpan utuh dan langsung terdeteksi tanpa menunggu output baru.
 */
function appendAutoEnterBuffer(session, rawData) {
  if (!session || !rawData || typeof rawData !== 'string') return;
  const clearIdx = Math.max(
    rawData.lastIndexOf('\x1b[2J'),
    rawData.lastIndexOf('\x1b[3J'),
    rawData.lastIndexOf('\x1bc')
  );
  let tail = rawData;
  if (clearIdx !== -1) {
    session.recentTextBuffer = '';
    tail = rawData.slice(clearIdx);
  }
  // Batasi ukuran tail mentah agar burst PTY besar tidak memicu scan regex multi-pass berkepanjangan
  const boundedTail = tail.length > 8192 ? tail.slice(-8192) : tail;
  const cleanedChunk = stripTerminalAnsiForMatcher(boundedTail);
  if (!cleanedChunk) return;
  session.recentTextBuffer = ((session.recentTextBuffer || '') + cleanedChunk).slice(-3000);
}

/**
 * Memasang pendengar output & exit PTY bersama untuk jalur SSE dan WebSocket:
 * - Fast-path 0ms untuk gema ketikan tunggal (< 64 karakter) pada WebSocket.
 * - Batching burst ConPTY (8ms / 32KB) agar streaming cepat tetap halus tanpa banjir frame WS.
 * - Melewati serialisasi JSON SSE saat tidak ada klien SSE terhubung.
 */
function attachPtySessionListeners(sessionId, session, ptyProcess, options = {}) {
  const closeSseOnExit = Boolean(options.closeSseOnExit);
  let pendingWsData = '';

  const flushWsBatch = () => {
    if (session._wsFlushTimer) {
      clearTimeout(session._wsFlushTimer);
      session._wsFlushTimer = null;
    }
    if (!pendingWsData) return;
    const out = pendingWsData;
    pendingWsData = '';
    if (session.wsClients && session.wsClients.size > 0) {
      const wsFrame = encodeWsFrame(JSON.stringify({ type: 'data', data: out, cleaned: true }));
      for (const ws of session.wsClients) {
        try { if (ws.writable) ws.write(wsFrame); } catch (_) {}
      }
    }
  };

  ptyProcess.onData((data) => {
    session.lastActivity = Date.now();
    if (typeof data === 'string' && data.includes('\x07')) {
      data = data.replace(/\x07/g, '');
    }
    if (!data) return;
    data = cleanConptyData(data, session);
    if (data.includes('\x1b[3J') || data.includes('\x1b[2J')) {
      session.buffer = [data];
    } else {
      if (session.buffer.length > 250) session.buffer.shift();
      session.buffer.push(data);
    }
    handleServerAutoEnter(session, data);

    if (session.clients && session.clients.size > 0) {
      const payload = `data: ${JSON.stringify({ type: 'data', data, cleaned: true })}\n\n`;
      for (const client of session.clients) {
        try { if (!client.writableEnded) client.write(payload); } catch (_) {}
      }
    }

    if (session.wsClients && session.wsClients.size > 0) {
      if (!session._wsFlushTimer && !pendingWsData && data.length < 64) {
        const wsFrame = encodeWsFrame(JSON.stringify({ type: 'data', data, cleaned: true }));
        for (const ws of session.wsClients) {
          try { if (ws.writable) ws.write(wsFrame); } catch (_) {}
        }
      } else {
        pendingWsData += data;
        if (pendingWsData.length >= 32768) {
          flushWsBatch();
        } else if (!session._wsFlushTimer) {
          session._wsFlushTimer = setTimeout(flushWsBatch, 8);
        }
      }
    }
  });

  ptyProcess.onExit(({ exitCode, signal }) => {
    flushWsBatch();
    if (session._autoEnterRetryTimer) {
      clearTimeout(session._autoEnterRetryTimer);
      session._autoEnterRetryTimer = null;
    }
    if (session._autoEnterActionTimer) {
      clearTimeout(session._autoEnterActionTimer);
      session._autoEnterActionTimer = null;
    }
    session.pty = null;
    if (session.clients && session.clients.size > 0) {
      const payload = `data: ${JSON.stringify({ type: 'exit', exitCode, signal })}\n\n`;
      for (const client of session.clients) {
        try {
          if (!client.writableEnded) {
            client.write(payload);
            client.end();
          }
        } catch (_) {}
      }
      session.clients.clear();
    }
    if (session.wsClients && session.wsClients.size > 0) {
      const wsFrame = encodeWsFrame(JSON.stringify({ type: 'exit', exitCode, signal }));
      for (const ws of session.wsClients) {
        try {
          if (ws.writable) {
            ws.write(wsFrame);
            ws.end();
          }
        } catch (_) {}
      }
      session.wsClients.clear();
    }
    if (activeTerminalSessions.get(sessionId) === session) {
      activeTerminalSessions.delete(sessionId);
    }
  });
}

/**
 * Catat aktivitas input manual pengguna dan reset epoch prompt bila pengguna mengirimkan
 * submit/interupsi eksplisit (\r, \n, Ctrl+C \x03, Esc \x1b) agar prompt lama yang sudah
 * dijawab manual tidak terpicu ulang saat Auto Enter dihidupkan kembali.
 */
function markSessionManualInput(session, rawInput) {
  if (!session) return;
  session.lastInputAt = Date.now();
  if (session._autoEnterActionTimer) {
    clearTimeout(session._autoEnterActionTimer);
    session._autoEnterActionTimer = null;
  }
  if (typeof rawInput === 'string' && /[\r\n\x03\x1b]/.test(rawInput)) {
    session.recentTextBuffer = '';
    if (session._autoEnterRetryTimer) {
      clearTimeout(session._autoEnterRetryTimer);
      session._autoEnterRetryTimer = null;
    }
  }
}

/**
 * Menentukan status awal Auto Enter untuk satu sesi PTY baru secara terisolasi per sessionId.
 */
function resolveInitialSessionAutoEnter(reqUrl, sessionId) {
  if (reqUrl && reqUrl.searchParams && reqUrl.searchParams.has('autoEnter')) {
    const raw = reqUrl.searchParams.get('autoEnter');
    return raw === '1' || raw === 'true';
  }
  if (sessionId && typeof sessionAutoEnterState !== 'undefined' && sessionAutoEnterState && sessionAutoEnterState.has(sessionId)) {
    return Boolean(sessionAutoEnterState.get(sessionId));
  }
  return false;
}

/**
 * Menerapkan status Auto Enter secara terisolasi HANYA ke sesi/jendela target yang diminta.
 * Tidak pernah mengubah status Auto Enter pada tab, panel split, atau jendela terminal lain.
 */
function syncAutoEnterState(enabled, sourceLabel = 'WS', targetSessionId = null) {
  const nextState = Boolean(enabled);
  const sid = (typeof targetSessionId === 'string' && targetSessionId.trim()) ? targetSessionId.trim() : null;

  const applyToSession = (id, s) => {
    if (!s) return;
    s.autoEnter = nextState;
    if (s._autoEnterRetryTimer) {
      clearTimeout(s._autoEnterRetryTimer);
      s._autoEnterRetryTimer = null;
    }
    if (nextState) {
      // Reset latch cooldown agar penyalaan ulang (0 -> 1) langsung aktif tanpa dead-lock
      s.lastAutoRespondAt = 0;
      setImmediate(() => {
        if (s && s.autoEnter && s.pty) {
          handleServerAutoEnter(s, '', { fromToggleOn: true });
        }
      });
    }
    const autoPayload = JSON.stringify({ type: 'auto-enter-status', autoEnter: nextState, session: id });
    if (s.clients) {
      for (const client of s.clients) {
        try { if (!client.writableEnded) client.write(`data: ${autoPayload}\n\n`); } catch (_) {}
      }
    }
    if (s.wsClients && s.wsClients.size > 0) {
      const wsFrame = encodeWsFrame(autoPayload);
      for (const ws of s.wsClients) {
        try { if (ws.writable) ws.write(wsFrame); } catch (_) {}
      }
    }
  };

  if (sid) {
    if (typeof sessionAutoEnterState !== 'undefined' && sessionAutoEnterState) {
      sessionAutoEnterState.set(sid, nextState);
    }
    const targetSession = activeTerminalSessions.get(sid);
    if (targetSession) {
      applyToSession(sid, targetSession);
    }
    console.log(`[AutoEnter] Updated session "${sid}" autoEnter=${nextState} via ${sourceLabel} (isolated window).`);
    return nextState;
  }

  // Fallback hanya bila pemanggil lawas tidak menyertakan targetSessionId sama sekali
  for (const [id, s] of activeTerminalSessions.entries()) {
    if (typeof sessionAutoEnterState !== 'undefined' && sessionAutoEnterState) {
      sessionAutoEnterState.set(id, nextState);
    }
    applyToSession(id, s);
  }
  console.log(`[AutoEnter] Synchronized autoEnter=${nextState} across active sessions via ${sourceLabel} (legacy broadcast).`);
  return nextState;
}

/**
 * Autonomous Server-Side Auto Y / Auto Enter Engine (Fixed-Point & Lossless Buffer)
 * Memantau output PTY secara real-time di background Windows host.
 * Ketika mendeteksi prompt perizinan (Claude Code, Antigravity CLI, Gemini CLI, PowerShell, npm),
 * server langsung mengirimkan konfirmasi (Enter / 'y\r') secara mandiri ke proses PTY.
 */
function handleServerAutoEnter(session, data, opts = {}) {
  if (!session || !session.pty) return;
  if (data && typeof data === 'string') {
    appendAutoEnterBuffer(session, data);
  }
  if (!session.autoEnter) return;

  if (session._autoEnterRetryTimer) {
    clearTimeout(session._autoEnterRetryTimer);
    session._autoEnterRetryTimer = null;
  }

  const now = Date.now();
  // Invarian jeda deterministik: hitung sisa tunda (holdoffMs). Jika > 0, jadwalkan ulang
  // tepat setelah jeda berakhir sehingga prompt yang masuk di jendela tunda TIDAK pernah hilang.
  const minWaitAuto = session.lastAutoRespondAt ? Math.max(0, 1000 - (now - session.lastAutoRespondAt)) : 0;
  const minWaitInput = (session.lastInputAt && !opts.ignoreRecentInput) ? Math.max(0, 1200 - (now - session.lastInputAt)) : 0;
  const holdoffMs = Math.max(minWaitAuto, minWaitInput);
  if (holdoffMs > 0) {
    session._autoEnterRetryTimer = setTimeout(() => {
      session._autoEnterRetryTimer = null;
      if (session && session.autoEnter && session.pty) {
        handleServerAutoEnter(session, '', { ignoreRecentInput: false });
      }
    }, holdoffMs + 25);
    return;
  }

  // Pertahankan batas baris agar guard prompt shell tidak tertembus kata historis di scrollback atas
  const recentLines = String(session.recentTextBuffer || '')
    .split('\n')
    .map(l => l.replace(/\s+/g, ' ').trim())
    .filter(Boolean);
  if (recentLines.length === 0) return;

  const lastLine = recentLines[recentLines.length - 1];
  // Guard: Jangan pernah auto-respond pada password/secret/PIN prompt
  if (/(?:password|passphrase|secret key|access token|api key|pin):\s*$/i.test(lastLine)) return;

  // Guard: Jika baris aktif paling bawah sudah kembali ke prompt shell biasa, hentikan
  if (/^(?:PS\s+[A-Z]:\\[^>]*>|[A-Z]:\\[^>]*>|[^@\s]+@[^:\s]+:[^$#]*[$#]|[$#>])$/i.test(lastLine)) {
    return;
  }

  // Fokuskan deteksi pada ekor aktif (maks. 10 baris / 650 karakter terakhir)
  const cleanFull = recentLines.slice(-10).join(' ');
  const clean = cleanFull.length > 650 ? cleanFull.slice(-650) : cleanFull;

  // Pola 1: Dialog menu / permission interaktif CLI (Claude Code, Gemini CLI, Antigravity CLI / AGY, Inquirer)
  const isCliAffirmativeMenu = (
    /(?:[>❯›→*]\s*(?:1\.|\(?1\)?|\[1\])?\s*(?:Yes|Allow|Accept|Approve|Proceed|Continue|Confirm|Run|Always|Apply|Save|Overwrite|Keep|Create|Update|Execute|Ya|Izinkan|Setujui|Lanjutkan)\b)/i.test(clean) ||
    (
      /(?:\bAllow\b|\bAccept\b|\bApprove\b|\bRun\b|\bExecute\b|\bProceed\b|\bConfirm\b|\bPermission\b|\bRequesting permission\b|\bDo you want to\b|\bWould you like to\b).*\?/i.test(clean) &&
      /(?:[>❯›→*]\s*1\.|\bNavigate\b|\btab Amend\b|\besc to cancel\b|\bf full diff\b|\bctrl\+r Review\b|\bauto-approve\b|[>❯›→*]\s*Yes\b)/i.test(clean)
    )
  );

  // Pola 2: Konfirmasi batch / CLI [y/N], (y/n), (yes/no), [Y/n]
  const isConfirmYPrompt = /(?:\[[yY]\/[nN]\]|\([yY]\/[nN]\)|\?.*\(Y\/n\)|\?.*\(y\/N\)|\(yes\/no\)|\[yes\/no\]|Terminate batch job \(Y\/N\)\?|\bdo you want to continue\s*\(?[yY]\/[nN]\)?|\bare you sure\s*\(?[yY]\/[nN]\)?|\bproceed with operation\s*\(?[yY]\/[nN]\)?|\bOk to proceed\? \([yY]\)|\bApakah Anda yakin|\bLanjutkan\?|\(yes\/no\/\[fingerprint\]\)|\bcontinue connecting\b)/i.test(clean);

  // Pola 3: Prompt "Press Enter to continue" / "Hit enter to continue"
  const isEnterOnlyPrompt = /(?:press (?:any key|enter) to continue|hit enter to continue|press \[enter\] to continue|\bpress enter to\b|\btekan enter untuk\b|\[enter\] to continue|\(enter to continue\))/i.test(clean);

  const scheduleAutoAction = (seq, label) => {
    if (session._autoEnterActionTimer) {
      clearTimeout(session._autoEnterActionTimer);
    }
    session._autoEnterActionTimer = setTimeout(() => {
      session._autoEnterActionTimer = null;
      if (session && session.pty && session.autoEnter) {
        try {
          session.pty.write(seq);
          console.log(`[AutoEnter] Session ${session.id}: ${label}`);
        } catch (_) {}
      }
    }, 120);
  };

  if (isCliAffirmativeMenu) {
    session.lastAutoRespondAt = now;
    session.recentTextBuffer = '';
    scheduleAutoAction('\r', 'Auto-approved CLI menu via Enter');
  } else if (isConfirmYPrompt) {
    session.lastAutoRespondAt = now;
    session.recentTextBuffer = '';
    scheduleAutoAction('y\r', "Auto-approved Y/N prompt via 'y\\r'");
  } else if (isEnterOnlyPrompt) {
    session.lastAutoRespondAt = now;
    session.recentTextBuffer = '';
    scheduleAutoAction('\r', "Auto-continued Enter prompt via '\\r'");
  }
}

