function executeZ21DocumentBuilderSandbox(rawPayload = {}, timeoutMs = 15000) {
  return new Promise((resolve) => {
    const startTime = Date.now();
    const spec = normalizeZ21DocSpec(rawPayload);
    const runId = 'z21_doc_' + Date.now() + '_' + crypto.randomBytes(4).toString('hex');
    const containerDir = path.join(Z21_DOC_CONTAINERS_ROOT, runId);
    fs.mkdirSync(containerDir, { recursive: true });

    const userPy = String(rawPayload.python_code || '').trim();
    const effectivePy = userPy || synthesizeZ21DocumentPythonScript(spec);
    const librariesUsed = [];
    if (/\breportlab\b/i.test(effectivePy)) librariesUsed.push('reportlab');
    if (/\bfpdf\b/i.test(effectivePy)) librariesUsed.push('fpdf');
    if (/\bweasyprint\b/i.test(effectivePy)) librariesUsed.push('weasyprint');
    if (/\bdocx\b/i.test(effectivePy)) librariesUsed.push('python-docx');
    if (/\bopenpyxl\b/i.test(effectivePy)) librariesUsed.push('openpyxl');
    if (/\bpandas\b/i.test(effectivePy)) librariesUsed.push('pandas');
    if (/\bxlsxwriter\b/i.test(effectivePy)) librariesUsed.push('xlsxwriter');
    if (librariesUsed.length === 0) librariesUsed.push(spec.format);

    const finalizeWithOutputFiles = (pyOutcome) => {
      let producedFiles = [];
      if (pyOutcome && pyOutcome.success === true) {
        const collectDocFiles = (dirPath) => {
          let entries = [];
          try { entries = fs.readdirSync(dirPath, { withFileTypes: true }); } catch (_) { return; }
          for (const ent of entries) {
            if (ent.name.startsWith('_zoz_') || ent.name.startsWith('fontlist') || ent.name.startsWith('.matplotlib') || ent.name === '__pycache__') continue;
            const fullPath = path.join(dirPath, ent.name);
            if (ent.isDirectory()) {
              collectDocFiles(fullPath);
            } else if (ent.isFile() && /\.(?:pdf|docx|xlsx|csv)$/i.test(ent.name)) {
              try {
                const st = fs.statSync(fullPath);
                if (st.size > 0 && st.size <= 15 * 1024 * 1024) producedFiles.push(fullPath);
              } catch (_) {}
            }
          }
        };
        collectDocFiles(containerDir);
      }

      let engine = pyOutcome && pyOutcome.success && producedFiles.length > 0 ? 'python-container-sandbox' : 'zoz-native-compiler';
      if (producedFiles.length === 0) {
        const nativeRes = compileZ21DocumentArtifactNode(spec, containerDir);
        producedFiles = [nativeRes.filePath];
        engine = nativeRes.engine;
      }

      const artifacts = producedFiles.map((fp) => {
        const buf = fs.readFileSync(fp);
        const fname = path.basename(fp);
        const ext = (fname.split('.').pop() || spec.format || 'pdf').toLowerCase();
        const mime = getZ21ArtifactMime(ext);
        const artifactId = 'art_' + Date.now().toString(36) + '_' + crypto.randomBytes(4).toString('hex');
        const usedLibs = engine === 'zoz-native-compiler' ? ['zoz-native'] : librariesUsed;
        registerZ21Artifact({
          id: artifactId,
          name: fname,
          mime,
          ext,
          buffer: buf,
          byteSize: buf.length,
          createdAt: new Date().toISOString(),
          engine,
          librariesUsed: usedLibs
        });
        let previewText = buildZ21PreviewMarkdown(spec, fname, ext, usedLibs, engine);
        if (ext === 'csv') {
          try { previewText = buf.toString('utf8').replace(/^\uFEFF/, ''); } catch (_) {}
        }
        return {
          artifactId,
          name: fname,
          mime,
          ext,
          byteSize: buf.length,
          size: buf.length < 1024 ? `${buf.length} B` : `${(buf.length / 1024).toFixed(1)} KB`,
          base64: buf.toString('base64'),
          downloadUrl: `/api/z21/artifacts/${artifactId}`,
          previewText,
          pythonScript: effectivePy,
          engine,
          librariesUsed: usedLibs
        };
      });

      if (IS_VERCEL_ENV) {
        try { fs.rmSync(containerDir, { recursive: true, force: true }); } catch (_) {}
      }

      const stdoutStr = (pyOutcome && pyOutcome.stdout) || '';
      let pdfQa;
      const qaM = stdoutStr.match(/^Z21_PDF_QA:(\{[^\r\n]+\})/m);
      if (qaM) {
        try { pdfQa = JSON.parse(qaM[1]); } catch (_) {}
      }

      resolve({
        success: true,
        engine,
        librariesUsed: engine === 'zoz-native-compiler' ? ['zoz-native'] : librariesUsed,
        stdout: stdoutStr,
        stderr: (pyOutcome && pyOutcome.stderr) || '',
        pythonFallbackReason: (pyOutcome && pyOutcome.fallbackReason) || undefined,
        ...(pdfQa ? { pdfQa } : {}),
        executionTimeMs: Date.now() - startTime,
        containerDir,
        files: artifacts
      });
    };

    const forceNative = Boolean(rawPayload.forceNative === true || rawPayload.library === 'zoz-native' || IS_VERCEL_ENV);
    if (forceNative) {
      return finalizeWithOutputFiles({ success: false, stdout: '', stderr: '', fallbackReason: IS_VERCEL_ENV ? 'vercel_serverless' : 'forceNative' });
    }

    const safety = validateZ21DocumentPythonSafety(effectivePy);
    if (!safety.safe) {
      return resolve({
        success: false,
        error: `Keamanan Sandbox Z21: ${safety.reason}`,
        executionTimeMs: Date.now() - startTime,
        files: []
      });
    }

    const futureImports = [];
    const bodyWithoutFuture = effectivePy.replace(/^[ \t]*(from\s+__future__\s+import\s+[^\r\n]+)/gm, (line) => {
      futureImports.push(line.trim());
      return '';
    });
    const specPath = path.join(containerDir, '_zoz_spec.json');
    const runnerPath = path.join(containerDir, '_zoz_runner.py');
    fs.writeFileSync(specPath, JSON.stringify(spec), 'utf8');
    const preludeHeader = futureImports.length > 0 ? futureImports.join('\n') + '\n' : '';
    fs.writeFileSync(runnerPath, preludeHeader + ZOZ_DOC_SANDBOX_PRELUDE_PY + '\n\n# --- USER SCRIPT ---\n' + bodyWithoutFuture + '\n', 'utf8');

    const pythonExec = process.env.PYTHON_EXEC || 'python';
    const safeEnv = {
      PYTHONIOENCODING: 'utf-8',
      PYTHONUTF8: '1',
      PYTHONUNBUFFERED: '1',
      MPLBACKEND: 'Agg',
      MPLCONFIGDIR: containerDir,
      ZOZ_OUTPUT_DIR: containerDir,
      ZOZ_DOC_SPEC_PATH: specPath,
      PATH: process.env.PATH || process.env.Path || '',
      Path: process.env.Path || process.env.PATH || '',
      SYSTEMROOT: process.env.SYSTEMROOT || 'C:\\Windows',
      WINDIR: process.env.WINDIR || 'C:\\Windows',
      TEMP: containerDir,
      TMP: containerDir,
      HOME: containerDir,
      USERPROFILE: containerDir
    };

    let proc;
    try {
      proc = spawn(pythonExec, ['-u', runnerPath], {
        stdio: ['ignore', 'pipe', 'pipe'],
        cwd: containerDir,
        windowsHide: true,
        env: safeEnv
      });
    } catch (spawnErr) {
      return finalizeWithOutputFiles({ success: false, stdout: '', stderr: spawnErr.message, fallbackReason: 'spawn_error' });
    }

    let stdoutData = '';
    let stderrData = '';
    let finished = false;
    const timer = setTimeout(() => {
      if (!finished) {
        finished = true;
        try { proc.kill(); } catch (_) {}
        finalizeWithOutputFiles({ success: false, stdout: stdoutData, stderr: stderrData, fallbackReason: 'timeout' });
      }
    }, Math.min(Math.max(Number(timeoutMs) || 15000, 2000), 30000));

    proc.stdout.on('data', (chunk) => {
      if (stdoutData.length < 12000) stdoutData += chunk.toString('utf8');
    });
    proc.stderr.on('data', (chunk) => {
      if (stderrData.length < 8000) stderrData += chunk.toString('utf8');
    });
    proc.on('error', (err) => {
      if (finished) return;
      finished = true;
      clearTimeout(timer);
      finalizeWithOutputFiles({ success: false, stdout: stdoutData, stderr: err.message, fallbackReason: 'proc_error' });
    });
    proc.on('close', (code) => {
      if (finished) return;
      finished = true;
      clearTimeout(timer);
      finalizeWithOutputFiles({
        success: code === 0,
        stdout: stdoutData.trim(),
        stderr: stderrData.trim(),
        fallbackReason: code !== 0 ? `exit_${code}` : undefined
      });
    });
  });
}


// OpenRouter Models In-Memory Optimization & CDN Cache (module-scoped to avoid sync disk I/O per request)
const OPENROUTER_MODELS_CACHE_FILE = path.join(DATA_DIR, 'openrouter-models-cache.json');
const OPENROUTER_MODELS_CACHE_TTL = 10 * 60 * 1000; // 10 menit
let cachedOpenRouterModelsPayload = null;
let cachedOpenRouterModelsAt = 0;

try {
  if (fs.existsSync(OPENROUTER_MODELS_CACHE_FILE)) {
    const stat = fs.statSync(OPENROUTER_MODELS_CACHE_FILE);
    const saved = JSON.parse(fs.readFileSync(OPENROUTER_MODELS_CACHE_FILE, 'utf8'));
    if (saved && Array.isArray(saved.data) && saved.data.length > 0) {
      cachedOpenRouterModelsPayload = saved;
      cachedOpenRouterModelsAt = stat.mtimeMs || 0;
    }
  }
} catch (_) {}

function isStrictLocalOriginHeader(req) {
  const headers = (req && req.headers) ? req.headers : {};
  const secFetchSite = String(headers['sec-fetch-site'] || '').trim().toLowerCase();
  if (secFetchSite === 'cross-site') return false;
  const checkLocalUrl = (rawUrl) => {
    try {
      const parsed = new URL(rawUrl);
      if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') return false;
      const host = String(parsed.hostname || '').toLowerCase();
      return host === 'localhost' || host === '127.0.0.1' || host === '::1' || host === '[::1]';
    } catch (_) {
      return false;
    }
  };
  const origin = headers.origin;
  if (origin) return checkLocalUrl(origin);
  const referer = headers.referer;
  if (referer) return checkLocalUrl(referer);
  return true;
}

function parseBoolParam(val, defaultValue = false) {
  if (val === undefined || val === null || val === '') return defaultValue;
  if (typeof val === 'boolean') return val;
  if (typeof val === 'number') return val !== 0;
  const s = String(val).trim().toLowerCase();
  if (s === 'true' || s === '1' || s === 'yes' || s === 'ya' || s === 'on') return true;
  if (s === 'false' || s === '0' || s === 'no' || s === 'tidak' || s === 'off' || s === 'null' || s === 'undefined') return false;
  return defaultValue;
}

const SENSITIVE_WORKSPACE_BASENAMES = new Set([
  'identities.json',
  'tunnel-state.json',
  'wa-config.json',
  'wa-master-config.json',
  'wa-contacts.json',
  'wa-messages.json',
  'wa-raw-media.json',
  'creds.json',
  'config.json',
  'secrets.json',
  'credentials.json',
  'openrouter-models-cache.json',
  'ollama-models-cache.json',
  'package-lock.json',
  'image_proxy.secret'
]);
const SENSITIVE_WORKSPACE_EXTS = new Set(['.key', '.pem', '.secret', '.p12', '.pfx', '.jks', '.keystore', '.env']);
const SENSITIVE_WORKSPACE_NAME_RE = /(?:^|[\/_.-])(?:secret|secrets|credential|credentials|password|passwd|private[_-]?key|service[_-]?account|api[_-]?key|access[_-]?token|auth[_-]?token|id_rsa)(?:$|[\/_.-])/i;

function isSensitiveWorkspaceFile(name, relPath = '') {
  const base = String(name || '').trim().toLowerCase();
  const rel = String(relPath || '').replace(/\\/g, '/').trim().toLowerCase();
  if (!base || base.startsWith('.')) return true;
  if (rel.split('/').some(seg => seg && seg.startsWith('.'))) return true;
  if (SENSITIVE_WORKSPACE_BASENAMES.has(base)) return true;
  const ext = path.extname(base);
  if (SENSITIVE_WORKSPACE_EXTS.has(ext)) return true;
  if (/^\.env(?:\.|$)/i.test(base) || /^env\.(?:local|prod|production|dev|secret)/i.test(base)) return true;
  if (SENSITIVE_WORKSPACE_NAME_RE.test(base) || SENSITIVE_WORKSPACE_NAME_RE.test(rel)) return true;
  return false;
}

function isPathContainedInRealRoot(realCandidate, realRoot) {
  if (!realCandidate || !realRoot) return false;
  const isWin = process.platform === 'win32';
  const cNorm = isWin ? realCandidate.toLowerCase() : realCandidate;
  const rNorm = isWin ? realRoot.toLowerCase() : realRoot;
  const prefix = rNorm.endsWith(path.sep) ? rNorm : (rNorm + path.sep);
  return cNorm === rNorm || cNorm.startsWith(prefix);
}

function normalizeCommPhoneDigits(val) {
  const rawDigits = String(val || '').replace(/\D/g, '');
  if (!rawDigits || rawDigits.length < 5) return [];
  const variants = new Set([rawDigits]);
  if (rawDigits.startsWith('08')) {
    variants.add('62' + rawDigits.slice(1));
  } else if (rawDigits.startsWith('628')) {
    variants.add('0' + rawDigits.slice(2));
  }
  return Array.from(variants);
}

