      if (!query || !query.trim()) {
        return sendJSON(res, 400, { error: 'Parameter query `q` atau body `{ query }` diperlukan.' });
      }
      const targetNum = Math.min(Math.max(isNaN(num) ? 15 : num, 1), 30);
      const data = await searchZozWebIndex(query, targetNum, context);
