        referenceImage = reqUrl.searchParams.get('referenceImage') || reqUrl.searchParams.get('image') || null;
        sessionId = reqUrl.searchParams.get('sessionId') || req.headers['x-session-id'] || req.headers['X-Session-ID'] || null;
